//! CI identity exchange against recorded JWKS and tokens
//! (`tests/fixtures/oidc/`, regenerated by `gen.py` with throwaway keys).
//! The clock is fixed, so the tokens never go stale.

use std::collections::BTreeMap;

use graft_auth::oidc::{
    Binding, Exchange, Issuer, Jwks, OidcError, Provider, pinned_changeset, verify_jwt,
};
use graft_auth::{NoDenylist, SigningKey, Token, verify};
use graft_proto::{ApiError, PrincipalKind};

const NOW: i64 = 1_800_000_000;
const GH_ISS: &str = "https://token.actions.githubusercontent.com";
const AUD: &str = "https://graft.example.test";
const WP_ISS: &str = "https://ci.example.test";
const WORKFLOW: &str =
    "TheDancingDeveloper-org/graft-ci/.github/workflows/graft-pre-land.yml@refs/heads/main";

fn tokens() -> BTreeMap<String, String> {
    serde_json::from_str(include_str!("fixtures/oidc/tokens.json")).unwrap()
}

fn tok(name: &str) -> String {
    tokens()
        .remove(name)
        .unwrap_or_else(|| panic!("no fixture {name}"))
}

fn github_jwks() -> Jwks {
    Jwks::from_json(include_str!("fixtures/oidc/github-jwks.json").as_bytes()).unwrap()
}

fn woodpecker_jwks() -> Jwks {
    Jwks::from_json(include_str!("fixtures/oidc/woodpecker-jwks.json").as_bytes()).unwrap()
}

fn github() -> Issuer {
    Issuer::new(
        Provider::GitHubActions,
        GH_ISS.into(),
        AUD.into(),
        github_jwks(),
    )
}

fn woodpecker() -> Issuer {
    Issuer::new(
        Provider::Woodpecker,
        WP_ISS.into(),
        AUD.into(),
        woodpecker_jwks(),
    )
}

fn gh_binding() -> Binding {
    Binding::new(
        Provider::GitHubActions,
        "TheDancingDeveloper-org/graft",
        "graft",
        &["repo:graft:read", "repo:graft:attest"],
    )
    .unwrap()
    .with_repo_id("900000001")
    .with_refs(&["refs/heads/graft/", "refs/heads/main"])
    .with_workflows(&[WORKFLOW])
}

fn wp_binding() -> Binding {
    Binding::new(
        Provider::Woodpecker,
        "indexarr/graft",
        "graft",
        &["repo:graft:read"],
    )
    .unwrap()
    .with_refs(&["refs/heads/graft/"])
}

fn exchange() -> Exchange {
    Exchange::new()
        .trust(github())
        .trust(woodpecker())
        .bind(gh_binding())
        .bind(wp_binding())
}

fn server_key() -> SigningKey {
    SigningKey::from_seed(&[0x42; 32])
}

const SHA: &str = "0123456789abcdef0123456789abcdef01234567";
const CHANGESET: &str = "cAbCdEf0123456789";

/// The pinned exchange, as the server runs it: the job's commit must be the
/// one exported for `CHANGESET` (here, `SHA`).
fn pin(x: &Exchange, key: &SigningKey, jwt: &str) -> Result<Token, OidcError> {
    x.exchange_pinned(key, jwt, NOW, CHANGESET, |sha| sha == SHA)
}

fn verify_graft(key: &SigningKey, t: &Token, now: i64) -> graft_auth::Claims {
    verify(&key.verifying_key(), t, now, &NoDenylist).unwrap()
}

#[test]
fn jwks_skips_keys_it_cannot_use() {
    // RSA 2048 (gh-test-1, gh-test-2) are usable. The 1024-bit key, the EC
    // key and the encryption key are skipped.
    assert_eq!(github_jwks().len(), 2);
    assert_eq!(woodpecker_jwks().len(), 1);
}

#[test]
fn jwks_rejects_non_documents() {
    for bad in [&b"{}"[..], b"[]", b"not json", b"{\"keys\":3}"] {
        assert_eq!(Jwks::from_json(bad).unwrap_err(), OidcError::Malformed);
    }
    assert!(Jwks::from_json(br#"{"keys":[]}"#).unwrap().is_empty());
}

#[test]
fn github_token_verifies() {
    let id = verify_jwt(&github(), &tok("gh_ok"), NOW).unwrap();
    assert_eq!(id.provider, Provider::GitHubActions);
    assert_eq!(id.repo, "TheDancingDeveloper-org/graft");
    assert_eq!(id.repo_id.as_deref(), Some("900000001"));
    assert_eq!(id.git_ref.as_deref(), Some("refs/heads/graft/wi-2265"));
    assert_eq!(id.exp, NOW + 240);
}

#[test]
fn audience_may_be_a_list() {
    verify_jwt(&github(), &tok("gh_aud_array"), NOW).unwrap();
}

#[test]
fn woodpecker_token_verifies() {
    let id = verify_jwt(&woodpecker(), &tok("wp_ok"), NOW).unwrap();
    assert_eq!(id.provider, Provider::Woodpecker);
    assert_eq!(id.repo, "indexarr/graft");
    // A numeric id is read as text.
    assert_eq!(id.repo_id.as_deref(), Some("42"));
}

#[test]
fn claims_are_checked() {
    let cases = [
        ("gh_wrong_aud", OidcError::WrongAudience),
        ("gh_no_aud", OidcError::WrongAudience),
        ("gh_wrong_iss", OidcError::WrongIssuer),
        ("gh_expired", OidcError::Expired),
        ("gh_exp_now", OidcError::Expired),
        ("gh_no_exp", OidcError::Malformed),
        ("gh_not_before", OidcError::NotYetValid),
        ("gh_future_iat", OidcError::NotYetValid),
        ("gh_long_lived", OidcError::Expired),
    ];
    for (name, want) in cases {
        assert_eq!(
            verify_jwt(&github(), &tok(name), NOW).unwrap_err(),
            want,
            "{name}"
        );
    }
}

#[test]
fn signature_and_key_are_checked() {
    let cases = [
        ("gh_wrong_key", OidcError::BadSignature),
        ("gh_tampered_payload", OidcError::BadSignature),
        ("gh_no_kid", OidcError::UnknownKey),
        ("gh_unknown_kid", OidcError::UnknownKey),
        // The 1024-bit key was skipped, so its kid is unknown.
        ("gh_small_key", OidcError::UnknownKey),
        // `alg` and key type disagree.
        ("gh_eddsa_on_rsa_key", OidcError::UnknownKey),
        ("gh_alg_none", OidcError::UnsupportedAlg),
        ("gh_hs256_public_key", OidcError::UnsupportedAlg),
        ("gh_four_parts", OidcError::Malformed),
        ("gh_two_parts", OidcError::Malformed),
    ];
    for (name, want) in cases {
        assert_eq!(
            verify_jwt(&github(), &tok(name), NOW).unwrap_err(),
            want,
            "{name}"
        );
    }
}

#[test]
fn a_woodpecker_token_does_not_verify_with_the_wrong_key() {
    assert_eq!(
        verify_jwt(&woodpecker(), &tok("wp_wrong_key"), NOW).unwrap_err(),
        OidcError::BadSignature
    );
}

#[test]
fn garbage_is_malformed() {
    for bad in ["", ".", "..", "a.b.c", "!!.!!.!!", &"x".repeat(32 * 1024)] {
        assert!(verify_jwt(&github(), bad, NOW).is_err(), "{bad:.20}");
    }
}

#[test]
fn leeway_covers_small_skew_only() {
    // `nbf` and `iat` are NOW - 60; the default leeway is 60 s.
    verify_jwt(&github(), &tok("gh_ok"), NOW - 119).unwrap();
    assert_eq!(
        verify_jwt(&github(), &tok("gh_ok"), NOW - 121).unwrap_err(),
        OidcError::NotYetValid
    );
}

// ---------------------------------------------------------------- exchange

#[test]
fn exchange_mints_a_short_ci_token() {
    let key = server_key();
    let t = pin(&exchange(), &key, &tok("gh_ok")).unwrap();
    let c = verify_graft(&key, &t, NOW);
    assert_eq!(c.principal.kind, PrincipalKind::Ci);
    assert_eq!(
        c.principal.subject,
        "ci:github:TheDancingDeveloper-org/graft#cAbCdEf0123456789"
    );
    assert_eq!(pinned_changeset(&c.principal.subject), Some(CHANGESET));
    assert_eq!(c.principal.scopes, ["repo:graft:read", "repo:graft:attest"]);
    // Attesting takes the dedicated scope, never a write (WI-2272).
    assert!(!c.principal.scopes.iter().any(|s| s.contains(":write")));
    assert_eq!(c.principal.session, None);
    assert_eq!(c.principal.work_item, None);
    // The CI token has 240 s left, under the 900 s default cap.
    assert_eq!(c.exp, NOW + 240);
}

#[test]
fn exchanged_token_never_outlives_the_ci_token() {
    let key = server_key();
    let t = pin(&exchange(), &key, &tok("gh_short_remaining")).unwrap();
    assert_eq!(verify_graft(&key, &t, NOW).exp, NOW + 30);
}

#[test]
fn exchanged_token_is_capped_by_max_ttl() {
    let key = server_key();
    let x = exchange().with_max_ttl_s(100);
    let t = pin(&x, &key, &tok("gh_ok")).unwrap();
    assert_eq!(verify_graft(&key, &t, NOW).exp, NOW + 100);
    // Never above the default cap.
    let x = exchange().with_max_ttl_s(86_400);
    let t = x.exchange_pinned(&key, &tok("gh_long_remaining"), NOW, CHANGESET, |_| true);
    assert_eq!(verify_graft(&key, &t.unwrap(), NOW).exp, NOW + 900);
}

#[test]
fn every_exchange_gets_its_own_jti() {
    let key = server_key();
    let x = exchange();
    let a = verify_graft(&key, &pin(&x, &key, &tok("gh_ok")).unwrap(), NOW);
    let b = verify_graft(&key, &pin(&x, &key, &tok("gh_ok")).unwrap(), NOW);
    assert_ne!(a.jti, b.jti);
}

#[test]
fn exchanged_token_is_signed_by_the_server_key_only() {
    let key = server_key();
    let t = pin(&exchange(), &key, &tok("gh_ok")).unwrap();
    let other = SigningKey::from_seed(&[7; 32]).verifying_key();
    assert!(verify(&other, &t, NOW, &NoDenylist).is_err());
}

#[test]
fn woodpecker_exchange() {
    let key = server_key();
    // A read-only binding needs no pin.
    let t = exchange().exchange(&key, &tok("wp_ok"), NOW).unwrap();
    let c = verify_graft(&key, &t, NOW);
    assert_eq!(c.principal.subject, "ci:woodpecker:indexarr/graft");
    assert_eq!(pinned_changeset(&c.principal.subject), None);
    assert_eq!(c.principal.scopes, ["repo:graft:read"]);
}

#[test]
fn a_token_for_another_repo_is_refused() {
    let key = server_key();
    for name in [
        "gh_other_repo",
        "gh_other_owner_same_name",
        "gh_tampered_payload",
    ] {
        let err = pin(&exchange(), &key, &tok(name)).unwrap_err();
        assert!(
            matches!(err, OidcError::RepoNotBound | OidcError::BadSignature),
            "{name}: {err:?}"
        );
    }
    // The clean case: a properly signed token for an unbound repository is
    // refused as a permission failure, not an authentication one.
    let err = pin(&exchange(), &key, &tok("gh_other_repo")).unwrap_err();
    assert_eq!(err, OidcError::RepoNotBound);
    assert!(matches!(
        ApiError::from(err),
        ApiError::PermissionDenied { .. }
    ));
    assert_eq!(
        pin(&exchange(), &key, &tok("wp_other_repo")).unwrap_err(),
        OidcError::RepoNotBound
    );
}

#[test]
fn repository_names_compare_case_insensitively_on_github_only() {
    let key = server_key();
    pin(&exchange(), &key, &tok("gh_mixed_case_repo")).unwrap();
    // Woodpecker names are exact.
    let strict = Binding::new(
        Provider::Woodpecker,
        "Indexarr/Graft",
        "graft",
        &["repo:graft:read"],
    )
    .unwrap();
    let x = Exchange::new().trust(woodpecker()).bind(strict);
    assert_eq!(
        pin(&x, &key, &tok("wp_ok")).unwrap_err(),
        OidcError::RepoNotBound
    );
}

#[test]
fn a_reused_repository_name_with_a_new_id_is_refused() {
    let key = server_key();
    assert_eq!(
        pin(&exchange(), &key, &tok("gh_reused_name_new_id")).unwrap_err(),
        OidcError::RepoNotBound
    );
}

#[test]
fn refs_outside_the_binding_are_refused() {
    let key = server_key();
    // `graft/` is a prefix rule; `refs/heads/main` is exact.
    pin(&exchange(), &key, &tok("gh_ok")).unwrap();
    pin(&exchange(), &key, &tok("gh_post_land_ref")).unwrap();
    for name in ["gh_ref_release", "gh_ref_prefix_trick", "gh_no_ref"] {
        assert_eq!(
            pin(&exchange(), &key, &tok(name)).unwrap_err(),
            OidcError::RefNotAllowed,
            "{name}"
        );
    }
    // With no ref rule any ref is accepted.
    let open = Binding::new(
        Provider::GitHubActions,
        "TheDancingDeveloper-org/graft",
        "graft",
        &["repo:graft:read"],
    )
    .unwrap();
    let x = Exchange::new().trust(github()).bind(open);
    pin(&x, &key, &tok("gh_ref_release")).unwrap();
    pin(&x, &key, &tok("gh_no_ref")).unwrap();
}

#[test]
fn only_the_pinned_workflow_may_exchange() {
    let key = server_key();
    // A workflow the repository's own branch added, asking for a token.
    for name in ["gh_own_workflow", "gh_workflow_other_ref", "gh_no_workflow"] {
        assert_eq!(
            pin(&exchange(), &key, &tok(name)).unwrap_err(),
            OidcError::WorkflowNotAllowed,
            "{name}"
        );
    }
    assert_eq!(
        verify_jwt(&github(), &tok("gh_ok"), NOW)
            .unwrap()
            .workflow
            .as_deref(),
        Some(WORKFLOW)
    );
}

#[test]
fn a_provider_cannot_use_another_providers_binding() {
    // A Woodpecker token claiming the repo name of a GitHub-only binding.
    let key = server_key();
    let x = Exchange::new().trust(woodpecker()).bind(gh_binding());
    assert_eq!(
        pin(&x, &key, &tok("wp_ok")).unwrap_err(),
        OidcError::RepoNotBound
    );
}

#[test]
fn unknown_issuer_is_refused() {
    let key = server_key();
    let x = Exchange::new().trust(woodpecker()).bind(wp_binding());
    assert_eq!(
        pin(&x, &key, &tok("gh_ok")).unwrap_err(),
        OidcError::WrongIssuer
    );
    assert_eq!(
        pin(&Exchange::new(), &key, &tok("gh_ok")).unwrap_err(),
        OidcError::WrongIssuer
    );
}

#[test]
fn a_token_is_checked_by_the_keys_of_the_issuer_it_names() {
    // Signed by GitHub's test key but claiming the Woodpecker issuer: it is
    // checked against Woodpecker's keys, where its `kid` is unknown.
    let key = server_key();
    assert_eq!(
        pin(&exchange(), &key, &tok("gh_signed_claiming_wp_issuer")).unwrap_err(),
        OidcError::UnknownKey
    );
}

#[test]
fn set_jwks_replaces_an_issuers_keys() {
    let key = server_key();
    let mut x = exchange();
    pin(&x, &key, &tok("gh_ok")).unwrap();
    assert!(x.set_jwks(GH_ISS, Jwks::from_json(br#"{"keys":[]}"#).unwrap()));
    assert_eq!(
        pin(&x, &key, &tok("gh_ok")).unwrap_err(),
        OidcError::UnknownKey
    );
    assert!(!x.set_jwks("https://nobody.example.test", github_jwks()));
}

#[test]
fn bindings_refuse_scopes_ci_must_not_hold() {
    let bind = |scopes: &[&str]| Binding::new(Provider::GitHubActions, "o/r", "graft", scopes);
    assert!(bind(&["repo:graft:read"]).is_ok());
    assert!(bind(&["repo:graft:read", "repo:graft:attest"]).is_ok());
    assert!(bind(&[]).is_err());
    // CI attests with `attest`; a write scope, even on an unused prefix,
    // would also let it open, move and close drafts (WI-2272).
    assert!(bind(&["repo:graft:write"]).is_err());
    assert!(bind(&["repo:graft:write:.ci"]).is_err());
    assert!(bind(&["repo:other:attest"]).is_err());
    assert!(bind(&["repo:graft:admin"]).is_err());
    assert!(bind(&["repo:graft:land:main"]).is_err());
    assert!(bind(&["objects:read"]).is_err());
    // Another repository's scope in this repository's binding.
    assert!(bind(&["repo:other:read"]).is_err());
    assert!(bind(&["nonsense"]).is_err());
    assert!(Binding::new(Provider::GitHubActions, "", "graft", &["repo:graft:read"]).is_err());
}

#[test]
fn errors_map_to_typed_api_errors() {
    assert_eq!(
        ApiError::from(OidcError::Expired),
        ApiError::Unauthenticated
    );
    assert_eq!(
        ApiError::from(OidcError::BadSignature),
        ApiError::Unauthenticated
    );
    assert!(matches!(
        ApiError::from(OidcError::RefNotAllowed),
        ApiError::PermissionDenied { .. }
    ));
    assert!(matches!(
        ApiError::from(OidcError::WorkflowNotAllowed),
        ApiError::PermissionDenied { .. }
    ));
}

#[test]
fn nothing_secret_appears_in_debug_or_display() {
    let t = tok("gh_ok");
    let body = t.split('.').nth(1).unwrap();
    let id = verify_jwt(&github(), &t, NOW).unwrap();
    let shown = format!(
        "{id:?} {:?} {:?} {}",
        github(),
        exchange(),
        OidcError::BadSignature
    );
    assert!(!shown.contains(body));
    assert!(!shown.contains(&t));
    assert!(!format!("{:?}", github_jwks()).contains("\"n\""));
}

// ----------------------------------------------------- pinning to a commit

#[test]
fn an_attest_binding_needs_a_pinned_exchange() {
    let key = server_key();
    assert_eq!(
        exchange().exchange(&key, &tok("gh_ok"), NOW).unwrap_err(),
        OidcError::PinRequired
    );
}

#[test]
fn the_job_must_have_run_on_the_changesets_commit() {
    // Another draft's trailer on a branch the attacker pushed: the commit the
    // job ran on is not the one exported for that draft.
    let key = server_key();
    let x = exchange();
    for name in ["gh_other_sha", "gh_no_sha"] {
        let err = pin(&x, &key, &tok(name)).unwrap_err();
        assert_eq!(err, OidcError::CommitMismatch, "{name}");
    }
    let err = x
        .exchange_pinned(&key, &tok("gh_ok"), NOW, CHANGESET, |_| false)
        .unwrap_err();
    assert_eq!(err, OidcError::CommitMismatch);
    assert!(matches!(
        ApiError::from(err),
        ApiError::PermissionDenied { .. }
    ));
}

#[test]
fn the_commit_check_sees_only_a_verified_sha_and_runs_last() {
    let key = server_key();
    let x = exchange();
    let mut seen = Vec::new();
    x.exchange_pinned(&key, &tok("gh_ok"), NOW, CHANGESET, |sha| {
        seen.push(sha.to_owned());
        true
    })
    .unwrap();
    assert_eq!(seen, [SHA]);
    // Refused earlier (wrong repo, bad signature, ref): never called.
    for name in [
        "gh_other_repo",
        "gh_wrong_key",
        "gh_ref_release",
        "gh_own_workflow",
    ] {
        let r = x.exchange_pinned(&key, &tok(name), NOW, CHANGESET, |_| {
            panic!("{name}: commit check ran before the other checks")
        });
        assert!(r.is_err(), "{name}");
    }
}

#[test]
fn a_pin_must_be_a_plain_id() {
    let key = server_key();
    for bad in ["", "c#x", "c x", "c/../x", &"c".repeat(65)] {
        let r = exchange().exchange_pinned(&key, &tok("gh_ok"), NOW, bad, |_| true);
        assert_eq!(r.unwrap_err(), OidcError::Malformed, "{bad:?}");
    }
}

#[test]
fn pinned_changeset_reads_only_pinned_ci_subjects() {
    assert_eq!(pinned_changeset("ci:github:o/r#cabc"), Some("cabc"));
    assert_eq!(pinned_changeset("ci:github:o/r"), None);
    assert_eq!(pinned_changeset("ci:github:o/r#"), None);
    assert_eq!(pinned_changeset("ses_01#cabc"), None);
    assert_eq!(pinned_changeset(""), None);
}

#[test]
fn an_attest_binding_must_name_refs_and_pin_the_workflow() {
    let key = server_key();
    let attest = |b: Binding| Exchange::new().trust(github()).bind(b);
    let base = || {
        Binding::new(
            Provider::GitHubActions,
            "TheDancingDeveloper-org/graft",
            "graft",
            &["repo:graft:read", "repo:graft:attest"],
        )
        .unwrap()
    };
    let no_refs = attest(base().with_workflows(&[WORKFLOW]));
    assert_eq!(
        pin(&no_refs, &key, &tok("gh_ok")).unwrap_err(),
        OidcError::RefNotAllowed
    );
    let no_workflow = attest(base().with_refs(&["refs/heads/graft/"]));
    assert_eq!(
        pin(&no_workflow, &key, &tok("gh_ok")).unwrap_err(),
        OidcError::WorkflowNotAllowed
    );
    let both = attest(
        base()
            .with_refs(&["refs/heads/graft/"])
            .with_workflows(&[WORKFLOW]),
    );
    pin(&both, &key, &tok("gh_ok")).unwrap();
}

#[test]
fn woodpecker_cannot_hold_an_attest_binding() {
    // A Woodpecker pipeline is the branch's own file; it cannot be pinned.
    let key = server_key();
    let b = Binding::new(
        Provider::Woodpecker,
        "indexarr/graft",
        "graft",
        &["repo:graft:attest"],
    )
    .unwrap()
    .with_refs(&["refs/heads/graft/"]);
    let x = Exchange::new().trust(woodpecker()).bind(b);
    assert_eq!(
        pin(&x, &key, &tok("wp_ok")).unwrap_err(),
        OidcError::WorkflowNotAllowed
    );
}

#[test]
fn a_repo_can_have_a_binding_per_workflow() {
    // Pre-land (graft/ branches) and post-land (main) as separate bindings;
    // the one whose rules the token passes is used.
    let key = server_key();
    let pre = Binding::new(
        Provider::GitHubActions,
        "TheDancingDeveloper-org/graft",
        "graft",
        &["repo:graft:read"],
    )
    .unwrap()
    .with_refs(&["refs/heads/graft/"])
    .with_workflows(&["other/ci/.github/workflows/pre.yml@refs/heads/main"]);
    let post = Binding::new(
        Provider::GitHubActions,
        "TheDancingDeveloper-org/graft",
        "graft",
        &["repo:graft:read", "repo:graft:attest"],
    )
    .unwrap()
    .with_refs(&["refs/heads/graft/"])
    .with_workflows(&[WORKFLOW]);
    let x = Exchange::new().trust(github()).bind(pre).bind(post);
    let t = pin(&x, &key, &tok("gh_ok")).unwrap();
    assert!(
        verify_graft(&key, &t, NOW)
            .principal
            .scopes
            .contains(&"repo:graft:attest".to_owned())
    );
    // None passes: the first refusal is reported.
    assert_eq!(
        pin(&x, &key, &tok("gh_own_workflow")).unwrap_err(),
        OidcError::WorkflowNotAllowed
    );
    assert_eq!(
        pin(&x, &key, &tok("gh_ref_release")).unwrap_err(),
        OidcError::RefNotAllowed
    );
}
